// Generated by AI (UnitTest MCP)
import { execFileSync } from "node:child_process";
import {
  appendFileSync,
  copyFileSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { afterEach, describe, expect, it } from "vitest";

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "../../..");
const gitattributes = join(repoRoot, ".gitattributes");
const temporaryDirectories = [];

/** Spawning real git repositories is slower than vitest's 5s default. */
const GIT_TEST_TIMEOUT_MS = 60_000;

// A child git process must not inherit the parent repository's pointers, or a
// fixture can write into the repository running the tests.
const gitRepositoryVariables = [
  "GIT_DIR",
  "GIT_WORK_TREE",
  "GIT_COMMON_DIR",
  "GIT_INDEX_FILE",
  "GIT_OBJECT_DIRECTORY",
  "GIT_ALTERNATE_OBJECT_DIRECTORIES",
];

const isolatedGitEnvironment = () => {
  const isolated = { ...process.env };
  for (const variable of gitRepositoryVariables) delete isolated[variable];
  return isolated;
};

afterEach(() => {
  for (const directory of temporaryDirectories.splice(0)) {
    rmSync(directory, { recursive: true, force: true });
  }
});

const git = (cwd, args) =>
  execFileSync("git", args, {
    cwd,
    encoding: "utf8",
    stdio: "pipe",
    env: isolatedGitEnvironment(),
  }).trim();

/**
 * A repository carrying this project's real `.gitattributes`, so the test
 * exercises the committed rule rather than a copy of it. Remove the union line
 * upstream and these tests fail.
 */
const repositoryWithProjectAttributes = (listFile) => {
  const repo = mkdtempSync(join(tmpdir(), "mindleak-union-merge-"));
  temporaryDirectories.push(repo);
  git(repo, ["init", "-b", "main"]);
  git(repo, ["config", "user.name", "Union Merge Test"]);
  git(repo, ["config", "user.email", "union@example.invalid"]);
  copyFileSync(gitattributes, join(repo, ".gitattributes"));
  mkdirSync(dirname(join(repo, listFile)), { recursive: true });
  writeFileSync(join(repo, listFile), "# List\n\n## [Unreleased]\n\n### Added\n");
  git(repo, ["add", ".gitattributes", listFile]);
  git(repo, ["commit", "-m", "base"]);
  return repo;
};

/** Two branches each append their own entry to the same spot, then merge. */
const mergeConcurrentAppends = (repo, listFile) => {
  git(repo, ["checkout", "-b", "fleet/first"]);
  appendFileSync(join(repo, listFile), "- entry from the first branch\n");
  git(repo, ["commit", "-am", "first entry"]);

  git(repo, ["checkout", "main"]);
  git(repo, ["checkout", "-b", "fleet/second"]);
  appendFileSync(join(repo, listFile), "- entry from the second branch\n");
  git(repo, ["commit", "-am", "second entry"]);

  let conflicted = false;
  try {
    git(repo, ["merge", "fleet/first", "--no-edit"]);
  } catch {
    conflicted = true;
  }
  return { conflicted, content: readFileSync(join(repo, listFile), "utf8") };
};

describe("append-only list merge", () => {
  /**
   * `CHANGELOG.md` used to carry the union driver too. It was removed with
   * ADR-0056: git honours the driver in a checkout but GitHub's merge machinery
   * does not, so a changelog-touching pull request reported a conflict that did
   * not exist and auto-merge silently went stale. Entries now live in
   * `changelog.d/` as one file per change, so two branches never write the same
   * path and there is nothing to merge.
   *
   * This asserts the removal rather than deleting the case: re-adding the
   * attribute would restore a conflict GitHub cannot resolve, and the next
   * person to hit it would have no record of why it was taken away.
   */
  it(
    "raises a real conflict on CHANGELOG.md, which no longer merges by union",
    () => {
      const repo = repositoryWithProjectAttributes("CHANGELOG.md");
      const { conflicted } = mergeConcurrentAppends(repo, "CHANGELOG.md");

      expect(conflicted).toBe(true);
    },
    GIT_TEST_TIMEOUT_MS
  );

  /**
   * The ADR index keeps the driver. It is generated by scripts/adr-index.mjs and
   * guarded by a hook, so a stale index is regenerated rather than merged —
   * union is a convenience here, not the mechanism.
   */
  it(
    "keeps both rows when two branches add an ADR to the index",
    () => {
      const repo = repositoryWithProjectAttributes("docs/adr/README.md");
      const { conflicted, content } = mergeConcurrentAppends(repo, "docs/adr/README.md");

      expect(conflicted).toBe(false);
      expect(content).toContain("- entry from the first branch");
      expect(content).toContain("- entry from the second branch");
    },
    GIT_TEST_TIMEOUT_MS
  );

  /**
   * DEVELOPERS.md is deliberately excluded. Its prose is revised in place, and
   * union merge never reports a conflict — silently keeping both copies of a
   * reworded paragraph is worse than being made to look.
   */
  it(
    "still raises a real conflict on DEVELOPERS.md",
    () => {
      const repo = repositoryWithProjectAttributes("DEVELOPERS.md");
      const { conflicted } = mergeConcurrentAppends(repo, "DEVELOPERS.md");

      expect(conflicted).toBe(true);
    },
    GIT_TEST_TIMEOUT_MS
  );

  it("declares union merge for exactly the generated index", () => {
    const declared = readFileSync(gitattributes, "utf8")
      .split(/\r?\n/)
      .filter((line) => /merge=union/.test(line) && !line.trimStart().startsWith("#"))
      .map((line) => line.split(/\s+/)[0])
      .sort();

    expect(declared).toEqual(["docs/adr/README.md"]);
  });
});
